import React, { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { X, Check } from "lucide-react";

const FABRIC_COLORS = [
  { id: "gold", name: "Royal Gold", hex: "#D4AF37" },
  { id: "champagne", name: "Champagne", hex: "#F7E7CE" },
  { id: "burgundy", name: "Deep Burgundy", hex: "#722F37" },
  { id: "ivory", name: "Classic Ivory", hex: "#FFFFF0" },
  { id: "rose-gold", name: "Rose Gold", hex: "#B76E79" },
  { id: "navy", name: "Midnight Navy", hex: "#1a1a3e" },
  { id: "emerald", name: "Emerald Green", hex: "#046307" },
  { id: "blush", name: "Blush Pink", hex: "#DE8F9C" },
  { id: "silver", name: "Silver Elegance", hex: "#C0C0C0" },
  { id: "maroon", name: "Rich Maroon", hex: "#800020" },
  { id: "pearl", name: "Pearl White", hex: "#FAFAFA" },
  { id: "royal-purple", name: "Royal Purple", hex: "#7851A9" },
];

const COLLECTIONS = [
  {
    id: "table-covers",
    name: "Round Table Covers",
    image: "https://images.pexels.com/photos/36547498/pexels-photo-36547498.jpeg?auto=compress&cs=tinysrgb&w=600"
  },
  {
    id: "chair-covers",
    name: "Chair Covers & Bows",
    image: "https://images.pexels.com/photos/32994472/pexels-photo-32994472.jpeg?auto=compress&cs=tinysrgb&w=600"
  },
  {
    id: "ceiling-drapes",
    name: "Ceiling Drapes",
    image: "https://images.pexels.com/photos/13156145/pexels-photo-13156145.jpeg?auto=compress&cs=tinysrgb&w=600"
  },
  {
    id: "floral",
    name: "Floral Materials",
    image: "https://images.pexels.com/photos/1469371670807/pexels-photo-1469371670807.jpeg?auto=compress&cs=tinysrgb&w=600"
  },
];

export default function ColorSelector() {
  const [selectedProduct, setSelectedProduct] = useState(null);
  const [selectedColors, setSelectedColors] = useState([]);
  const [showModal, setShowModal] = useState(false);

  const toggleColor = (colorId) => {
    setSelectedColors(prev =>
      prev.includes(colorId)
        ? prev.filter(c => c !== colorId)
        : [...prev, colorId]
    );
  };

  const handleQuote = () => {
    const colors = selectedColors.map(c => FABRIC_COLORS.find(fc => fc.id === c)?.name).join(", ");
    const product = COLLECTIONS.find(p => p.id === selectedProduct)?.name || "";
    const message = `*Color/Fabric Selection - D SAJAWAT*\n\n*Product:* ${product}\n*Selected Colors:* ${colors || "To be discussed"}\n\nHi! I'm interested in these fabric options. Please share availability and pricing.`;
    window.open(`https://wa.me/919888919983?text=${encodeURIComponent(message)}`, "_blank");
    setShowModal(false);
    setSelectedColors([]);
  };

  return (
    <section className="py-16 md:py-24" style={{ background: "#ffffff" }}>
      <div className="px-6 md:px-12 lg:px-24">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.8 }}
          className="text-center mb-12"
        >
          <p className="text-xs tracking-[0.3em] uppercase mb-3" style={{ color: "#d4af37" }}>Customization</p>
          <h2 className="serif text-3xl md:text-4xl mb-4" style={{ color: "#1a080a" }}>
            Choose Your <span style={{ color: "#d4af37", fontStyle: "italic" }}>Perfect Color</span>
          </h2>
          <p className="text-base max-w-xl mx-auto" style={{ color: "rgba(26,8,10,0.6)" }}>
            Select from our premium color palette. Tell us your event theme and we'll suggest the perfect fabrics.
          </p>
        </motion.div>

        {/* Product Cards */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-8">
          {COLLECTIONS.map((product, i) => (
            <motion.div
              key={product.id}
              initial={{ opacity: 0, y: 20 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.5, delay: i * 0.1 }}
              className="cursor-pointer rounded-xl overflow-hidden"
              style={{
                border: selectedProduct === product.id ? "3px solid #d4af37" : "2px solid rgba(212,175,55,0.2)",
                boxShadow: selectedProduct === product.id ? "0 8px 30px rgba(212,175,55,0.3)" : "none"
              }}
              onClick={() => setSelectedProduct(product.id)}
            >
              <div className="relative h-32 overflow-hidden">
                <img src={product.image} alt={product.name} className="w-full h-full object-cover" />
                {selectedProduct === product.id && (
                  <div className="absolute top-2 right-2 w-6 h-6 rounded-full flex items-center justify-center" style={{ background: "#d4af37" }}>
                    <Check size={14} color="white" />
                  </div>
                )}
              </div>
              <div className="p-3 text-center" style={{ background: selectedProduct === product.id ? "rgba(212,175,55,0.1)" : "white" }}>
                <p className="text-sm font-medium" style={{ color: "#1a080a" }}>{product.name}</p>
              </div>
            </motion.div>
          ))}
        </div>

        {/* Color Palette */}
        {selectedProduct && (
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5 }}
            className="text-center"
          >
            <h3 className="text-lg font-semibold mb-4" style={{ color: "#1a080a" }}>
              Select Colors for {COLLECTIONS.find(p => p.id === selectedProduct)?.name}
            </h3>

            <div className="flex flex-wrap justify-center gap-3 mb-8">
              {FABRIC_COLORS.map((color) => (
                <motion.button
                  key={color.id}
                  whileHover={{ scale: 1.1 }}
                  whileTap={{ scale: 0.95 }}
                  onClick={() => toggleColor(color.id)}
                  className="relative w-14 h-14 rounded-full transition-all"
                  style={{
                    background: color.hex,
                    border: selectedColors.includes(color.id) ? "3px solid #1a080a" : "2px solid rgba(212,175,55,0.3)",
                    boxShadow: selectedColors.includes(color.id)
                      ? `0 4px 15px ${color.hex}80`
                      : "0 2px 8px rgba(0,0,0,0.1)"
                  }}
                  title={color.name}
                >
                  {selectedColors.includes(color.id) && (
                    <div className="absolute -top-1 -right-1 w-5 h-5 rounded-full flex items-center justify-center" style={{ background: "#d4af37" }}>
                      <Check size={12} color="white" />
                    </div>
                  )}
                </motion.button>
              ))}
            </div>

            <motion.button
              whileHover={{ scale: 1.02 }}
              whileTap={{ scale: 0.98 }}
              onClick={handleQuote}
              disabled={selectedColors.length === 0}
              className="btn-gold px-8 py-3"
              style={{ opacity: selectedColors.length ? 1 : 0.5 }}
            >
              Get Quote for Selected Colors ({selectedColors.length} selected)
            </motion.button>
          </motion.div>
        )}

        {/* Selected Colors Summary */}
        {selectedColors.length > 0 && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            className="mt-8 text-center"
          >
            <p className="text-sm" style={{ color: "rgba(26,8,10,0.6)" }}>
              Selected: {selectedColors.map(c => FABRIC_COLORS.find(fc => fc.id === c)?.name).join(", ")}
            </p>
          </motion.div>
        )}
      </div>
    </section>
  );
}
